theory.code:
int flags = 0b101101;
System.out.println(Integer.toBinaryString(flags)); // 101101

// Sprawdzenie, czy bit nr 2 (licząc od 0) jest ustawiony:
int mask = 1 << 2; // 000100
boolean isSet = (flags & mask) != 0;
System.out.println("Bit 2 ustawiony: " + isSet);

// Ustawienie, wyczyszczenie, przelaczenie bitu:
int setBit = flags | (1 << 1);   // ustawia bit 1
int clearBit = flags & ~(1 << 0); // zeruje bit 0
int toggleBit = flags ^ (1 << 3); // przełącza bit 3

// Formatowanie z zerami wiodacymi:
int value = 7;
String padded = String.format("%8s", Integer.toBinaryString(value)).replace(' ', '0');
System.out.println(padded); // 00000111

