int[] values = {0, 1, 10, 15, 16, 127, 255};
for (int n : values) {
    System.out.println("n=" + n + " | bin=" + Integer.toBinaryString(n)
            + " | oct=" + Integer.toOctalString(n) + " | hex=" + Integer.toHexString(n));
}

String color = "#FF5733";
int r = Integer.parseInt(color.substring(1, 3), 16);
int g = Integer.parseInt(color.substring(3, 5), 16);
int b = Integer.parseInt(color.substring(5, 7), 16);
System.out.println("R=" + r + ", G=" + g + ", B=" + b);

int n = 42;
String binary = "";
while (n > 0) {
    binary = (n % 2) + binary;
    n /= 2;
}
System.out.println(binary);

String bin = "101010";
int result = 0;
int power = 1;
for (int i = bin.length() - 1; i >= 0; i--) {
    int digit = bin.charAt(i) - '0';
    result += digit * power;
    power *= 2;
}
System.out.println(result);

System.out.println("Dec | Bin    | Oct | Hex");
for (int i = 0; i <= 15; i++) {
    System.out.printf("%3d | %6s | %3s | %s%n", i, Integer.toBinaryString(i), Integer.toOctalString(i), Integer.toHexString(i));
}

int READ = 1 << 0, WRITE = 1 << 1, EXECUTE = 1 << 2;
int permissions = READ | WRITE;
System.out.println("Ma READ: " + ((permissions & READ) != 0));
System.out.println("Ma WRITE: " + ((permissions & WRITE) != 0));
System.out.println("Ma EXECUTE: " + ((permissions & EXECUTE) != 0));

permissions &= ~WRITE;
System.out.println("Po usunieciu WRITE:");
System.out.println("Ma WRITE: " + ((permissions & WRITE) != 0));

int rgb = 0x1A2B3C;
int r = (rgb >> 16) & 0xFF;
int g = (rgb >> 8) & 0xFF;
int b = rgb & 0xFF;
System.out.println("R=" + r + ", G=" + g + ", B=" + b);

int r = 255, g = 128, b = 0;
int packed = (r << 16) | (g << 8) | b;
System.out.println("Packed hex: " + Integer.toHexString(packed));

int r2 = (packed >> 16) & 0xFF;
int g2 = (packed >> 8) & 0xFF;
int b2 = packed & 0xFF;
System.out.println("Odzyskane: R=" + r2 + ", G=" + g2 + ", B=" + b2);

int[] values = {1, 2, 3, 4, 8, 10, 16, 100};
for (int n : values) {
    boolean isPowerOfTwo = n > 0 && (n & (n - 1)) == 0;
    System.out.println(n + " jest potęga 2: " + isPowerOfTwo);
}

int n = 42;
int original = n;
int count = 0;
while (n != 0) {
    count += (n & 1);
    n >>>= 1;
}
System.out.println("Ręcznie: " + count);
System.out.println("Integer.bitCount: " + Integer.bitCount(original));

String a = "1010", b = "1100";
int intA = Integer.parseInt(a, 2);
int intB = Integer.parseInt(b, 2);

int andResult = intA & intB;
int orResult = intA | intB;
int xorResult = intA ^ intB;

System.out.println("A AND B = " + andResult + " (binarnie: " + Integer.toBinaryString(andResult) + ")");
System.out.println("A OR B = " + orResult + " (binarnie: " + Integer.toBinaryString(orResult) + ")");
System.out.println("A XOR B = " + xorResult + " (binarnie: " + Integer.toBinaryString(xorResult) + ")");

